// Return only a subset of fields in the response.
fields_application?: Array<"articles" | "banner_image_url" | "categories" | "client_id" | "created_at" | "description" | "developed_by" | "features" | "gallery_items" | "icon_url" | "id" | "install_url" | "name" | "oauth_callback_urls" | "preferences_link" | "pricing_information_link" | "privacy_policy_link" | "scopes" | "short_description" | "status" | "support_link" | "video" | "video.video_id" | "website_link"> | null, // default: null
